<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue';
import type {Trace} from '../api';import type {SourceRange} from '../generated/SourceRange';import {useLab} from '../store';import {framesFor,type DetailMode} from '../animation/timeline';import {usePlayback} from '../animation/usePlayback';import MotionControls from './MotionControls.vue';import AnimationStage from './AnimationStage.vue';import GraphView from './GraphView.vue';
const focusButton=ref<HTMLButtonElement>();
const props=defineProps<{trace:Trace}>();const emit=defineEmits<{highlight:[SourceRange|null]}>();const lab=useLab();
const preferences=lab.workspace?.view;const saved=preferences&&typeof preferences==='object'&&!Array.isArray(preferences)&&'motion'in preferences?preferences.motion:null;
const mode=ref<DetailMode>(saved&&typeof saved==='object'&&!Array.isArray(saved)&&saved.detail==='full'?'full':'sample');
const media=matchMedia('(prefers-reduced-motion: reduce)');const reduced=ref(saved&&typeof saved==='object'&&!Array.isArray(saved)&&typeof saved.reduced==='boolean'?saved.reduced:media.matches);const focus=ref(false);const inspection=ref<string>();
const frames=computed(()=>framesFor(props.trace,mode.value));const count=computed(()=>frames.value.length);const playback=usePlayback(count);const {index,progress,playing,speed}=playback;
const frame=computed(()=>frames.value[index.value]);const step=computed(()=>frame.value?props.trace.steps[frame.value.stepIndex]:undefined);
const expression=computed(()=>{const r=step.value?.source_range;if(!r)return step.value?.title??'';const lines=props.trace.source.split('\n').slice(r.line-1,r.end_line);return lines.map((line,i)=>line.slice(i===0?r.column-1:0,i===lines.length-1?r.end_column-1:undefined)).join('\n')||step.value?.title;});
const nodes=computed(()=>props.trace.steps.map(s=>({id:String(s.id),label:s.title,detail:`${s.table.rows.length} 行 · ${s.kind}`})));
const edges=computed(()=>props.trace.steps.flatMap(s=>s.parents.map(p=>({id:`${p}:${s.id}`,source:String(p),target:String(s.id)}))));
const neighborhood=computed(()=>{const current=step.value;if(!current)return[];const ids=new Set([current.id,...current.parents]);const next=props.trace.steps[(frame.value?.stepIndex??0)+1];if(next)ids.add(next.id);return props.trace.steps.filter(s=>ids.has(s.id));});
const rule=computed(()=>({source:'读取冻结关系中的独立记录实例。',join:'按 ON 条件匹配；外连接按规则保留未匹配记录并补 NULL。',filter:'WHERE 只保留 TRUE；FALSE 和 UNKNOWN 均被过滤。',group:'按分组键形成组；NULL 分组键归在同一组。',aggregate:'聚合基于组内记录；COUNT(列) 忽略 NULL，COUNT(*) 统计全部记录。',having:'HAVING 筛选聚合后的组。',distinct:'DISTINCT 合并同值输出；重复行实例仍可追溯。',sort:'ORDER BY 定义输出顺序；并列项可能没有唯一顺序。',limit:'分页截取排序或冻结枚举中的指定区间。',project:'选择输出属性；SQL 的普通投影保留重复次数。'}[step.value?.kind??'']??step.value?.explanation??''));
function keys(e:KeyboardEvent){if((e.target as HTMLElement).closest('input,textarea,select,.monaco-editor'))return;if(e.key==='Escape'){focus.value=false;focusButton.value?.focus();return}if(e.key===' '){e.preventDefault();toggle()}else if(e.key==='ArrowRight'){e.preventDefault();playback.seek(index.value+1)}else if(e.key==='ArrowLeft'){e.preventDefault();playback.seek(index.value-1)}}
const completed=computed(()=>props.trace.steps.slice(0,frame.value?.stepIndex??0).map(s=>String(s.id)));
function jump(id:string){const n=frames.value.findIndex(f=>String(f.step)===id);if(n>=0){inspection.value=undefined;playback.seek(n);}}
function toggle(){inspection.value=undefined;playback.toggle()}
function inspect(n:string){playback.pause();inspection.value=n;}
watch(()=>props.trace,()=>{playback.seek(0);inspection.value=undefined;});
watch(()=>step.value?.source_range,r=>emit('highlight',r??null),{immediate:true});
watch([mode,reduced],()=>{playback.seek(0);if(lab.workspace){const old=lab.workspace.view;lab.workspace.view={...(old&&typeof old==='object'&&!Array.isArray(old)?old:{}),motion:{detail:mode.value,reduced:reduced.value}};lab.dirty=true;}});
onBeforeUnmount(()=>emit('highlight',null));
</script>
<template><div class="trace-view" tabindex="0" aria-label="查询回放，空格播放，左右键逐步，Escape 退出专注" @keydown="keys" :class="{'focus-view':focus,'reduced-motion':reduced}"><div class="trace-heading"><div><span class="eyebrow">LIVE LEARNING · 冻结过程回放</span><strong>看清每条记录的去向</strong></div><div class="toolbar"><select v-model="mode" aria-label="演示记录范围"><option value="sample">重点逐行 · 其余合批</option><option value="full">完整逐行</option></select><label class="check"><input v-model="reduced" type="checkbox">减少动态效果</label><button ref="focusButton" @click="focus=!focus" data-testid="focus-motion">{{focus?'退出专注':'专注演示 ↗'}}</button></div></div><details class="trace-snapshot" :open="trace.status!=='completed'"><summary>{{trace.status==='completed'?'✓ 同一快照 · 结果已核对（展开来源）':trace.message}}</summary><p>{{trace.message}}</p><small>{{trace.snapshot}}</small></details><template v-if="frame&&step"><div class="motion-sticky"><nav class="local-flow" aria-label="当前操作附近的流程"><button v-for="s in neighborhood" :key="s.id" :aria-current="s.id===step.id?'step':undefined" :class="{active:s.id===step.id}" @click="jump(String(s.id))">{{s.id===step.id?'当前操作':step.parents.includes(s.id)?'输入':'下一步'}}<strong>{{s.title}}</strong><small>{{s.table.rows.length}} 行</small></button></nav><details class="global-flow"><summary>展开完整流程 · 平移、缩放、导出</summary><GraphView :nodes="nodes" :edges="edges" :selected="String(step.id)" :completed="completed" :progress="progress" :reduced="reduced" @select="jump"/></details><MotionControls :index="index" :count="count" :progress="progress" :playing="playing" :speed="speed" :label="`操作 ${frame.stepIndex+1}/${trace.steps.length} · ${step.title}`" @seek="inspection=undefined;playback.seek($event)" @toggle="toggle" @speed="speed=$event"/></div><div class="motion-legend"><span class="active">● 当前处理</span><span class="keep">✓ 保留／产生</span><span class="drop">− 筛除</span><span class="unknown">? NULL／UNKNOWN</span><span class="danger">! 冲突</span></div><div class="expression-highlight"><span>{{step.kind.toUpperCase()}}</span><code>{{expression}}</code></div><section class="teaching-layer" aria-live="polite"><h3>这一步为什么这样？</h3><p><b>正在处理：</b>{{frame.message}}</p><p><b>依据规则：</b>{{rule}}</p><p><b>结果依据：</b>{{frame.certainty==='candidate'?'存在多个可能来源，不能唯一定位输入实例。':frame.truth?`数据库谓词结果为 ${frame.truth}。`:'来自本次冻结快照与关联事件。'}} 当前操作输出共 {{step.table.rows.length}} 行。</p></section><AnimationStage :trace="trace" :frame="frame" :progress="progress" :reduced="reduced" :inspection="inspection" @inspect="inspect"/><div class="step-explanation"><h3>{{step.title}}</h3><p>{{step.explanation}}</p><details><summary>验证 SQL 与冻结来源</summary><pre>{{step.sql}}</pre><small>过程播放不会重新访问数据库。记录号是当前冻结关系中的实例，不是物理行号。</small></details></div><nav class="operation-chips"><button v-for="s in trace.steps" :key="s.id" :class="{active:s.id===step.id}" @click="jump(String(s.id))">{{s.title}} <small>{{s.table.rows.length}} 行</small></button></nav></template><div v-else class="empty">当前过程没有可播放事件。</div></div></template>
